.article-body {
  text-align: justify;
  -webkit-hyphens: auto; /* Safari compatibility */
  -ms-hyphens: auto;     /* IE/Edge compatibility */
  hyphens: auto;
  hyphenate-limit-chars: 6 3 3; /* Optional: min word length, chars before/after hyphen */
  hyphenate-limit-lines: 2;    /* Optional: max consecutive hyphenated lines */
}
